<script lang="ts">import{idempotencyKey}from'$lib/api/client';let identifier='',channel='email',requestID='',factor_type='recovery_code',proof='',message='',busy=false;async function start(){busy=true;const r=await fetch('/api/v1/account-recovery/requests',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':idempotencyKey()},body:JSON.stringify({identifier,channel})});const d=await r.json().catch(()=>({}));busy=false;requestID=d.development_request_id??'';message=d.message??'If eligible, recovery instructions have been sent.'}async function addEvidence(){busy=true;const r=await fetch(`/api/v1/account-recovery/requests/${requestID}/evidence`,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':idempotencyKey()},body:JSON.stringify({factor_type,proof})});const d=await r.json().catch(()=>({}));busy=false;message=r.ok?d.message:(d.detail??'Evidence could not be verified.');proof=''}</script>
<svelte:head><title>Get back into your account — Kredit</title></svelte:head><main class="shell recovery"><a href="/">Kredit</a><p class="eyebrow">Account help</p><h1>Get back into your account.</h1><p>We will ask for more than your phone number. This keeps another person from taking your account.</p>{#if message}<p class="notice" role="status">{message}</p>{/if}<section><label>Your email or phone<input bind:value={identifier} autocomplete="username"/></label><label>Which one did you enter?<select bind:value={channel}><option value="email">Email</option><option value="phone">Phone</option></select></label><button onclick={start} disabled={busy||!identifier}>Help me sign in</button></section>{#if requestID}<section><h2>Enter your recovery code</h2><label class="sr-only">Code type<select bind:value={factor_type}><option value="recovery_code">Recovery code</option></select></label><label>Recovery code<input bind:value={proof} autocomplete="one-time-code"/></label><button onclick={addEvidence} disabled={busy||!proof}>Check this code</button><p>We will send the other steps separately. Each recovery code works only once.</p></section>{/if}</main>
<style>.recovery{max-width:42rem;padding-top:4rem}.recovery h1{font-size:clamp(2.5rem,7vw,5rem);line-height:1}.recovery section{display:grid;gap:.8rem;margin:1rem 0;padding:1.3rem;border:1px solid var(--color-border);border-radius:1rem;background:var(--color-surface)}label{display:grid;gap:.35rem;font-weight:700}input,select,button{padding:.8rem;border:1px solid var(--color-border);border-radius:.65rem;font:inherit}button{background:var(--color-primary);color:white;font-weight:800}.notice{padding:1rem;background:#eef5ff;border-radius:.7rem}</style>
